// Intent (Benjamin, 2026-10-11): « trop de texte, trop de detail trop de contenu […] l’interface doit etre simple ».
// Mechanism: actual cockpit rendering, only the result's detail varies; all state is in memory.
const qp=new URLSearchParams(location.search), variants=['A','B','C'];
const names={A:'Trois onglets',B:'Une action à la fois',C:'Accès directs'};
const titles={ready:'Le cockpit attend ton jugement',dossier:'Le dossier du résultat',trial:'Le résultat est ouvert pour ton essai',findings:'Préparer tes constats',returned:'Tes constats ont été rendus',repairing:'L’usine corrige tes constats','new-result':'Un nouveau résultat attend ton jugement',accepted:'Accepté · fusion en attente',merging:'La fusion est en cours',merged:'Le résultat est fusionné',outdated:'Le dossier doit être renouvelé',outage:'Le produit ne démarre pas',conflict:'Un nouveau jugement sera nécessaire',abandoned:'Le chantier est abandonné'};
const screens={ready:'result',dossier:'dossier',trial:'trial',findings:'findings',returned:'follow',repairing:'follow','new-result':'result',accepted:'follow',merging:'follow',merged:'follow',outdated:'dossier',outage:'trial',conflict:'follow',abandoned:'follow'};
const labels={result:'Résultat',dossier:'Dossier',trial:'Essai',findings:'Mes constats',follow:'Suivi'};
let variant=variants.includes(qp.get('variant'))?qp.get('variant'):'B',scene=titles[qp.get('scene')]?qp.get('scene'):'ready';
let screen=qp.get('view')&&labels[qp.get('view')]?qp.get('view'):screens[scene],version=scene==='new-result'?2:1,sessionOpen=scene==='trial',trialDone=false,words='',answer='constats',citation='parcours',proposition='',reason='',dataset='Avec une demande',draftPrompt='',notice='',selected='demo-result',sheet=false,dossierRead=false;
const detail=document.getElementById('d-demo-result'), root=document.getElementById('inbox');
document.addEventListener('submit',e=>e.preventDefault());
document.querySelectorAll('[data-action]').forEach(b=>{b.disabled=true;b.title='Commande réelle inactive dans le prototype';});
document.querySelectorAll('form button').forEach(b=>{b.type='button';b.disabled=true;});
const prototypeSource={base:'f65d23e',requests:'synthetic',commandsExecuted:0};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function action(label,fn,primary=false,disabled=false){return `<button type="button" class="btn ${primary?'primary':''}" onclick="${fn}" ${disabled?'disabled':''}>${label}</button>`;}
function needHuman(){return !['returned','repairing','accepted','merging','merged','abandoned','outage','conflict','outdated'].includes(scene);}
function state(){return {prototype:true,variant,scene,screen,dossier:{version,read:dossierRead,current:!['outdated','conflict'].includes(scene)},session:{open:sessionOpen,dataset,trialDone},draft:{answer,words,citation,proposition,reason},answerRecorded:['returned','repairing','accepted','merging','merged','conflict','abandoned'].includes(scene),acceptanceValid:['accepted','merging','merged'].includes(scene),merged:scene==='merged',needsHuman:needHuman(),productionWrites:0,...prototypeSource};}
function sync(){const u=new URL(location.href);u.searchParams.set('variant',variant);u.searchParams.set('scene',scene);u.searchParams.set('view',screen);history.replaceState(null,'',u);document.getElementById('prototype-state').textContent=JSON.stringify(state(),null,2);}
function show(view){screen=view;if(view==='dossier')dossierRead=true;sheet=true;sync();render();}
function setScene(s){scene=s;screen=screens[s];selected='demo-result';sheet=true;sessionOpen=s==='trial';version=s==='new-result'?2:version;draftPrompt='';notice='';sync();render();}
function trialLink(label,primary=false){return `<a class="btn ${primary?'primary':''}" href="?app=trial&dossier=${version}" target="_blank" rel="noopener" onclick="startTrial()">${label}</a>`;}
function startTrial(){if(!editable())return;sessionOpen=true;screen='trial';sheet=true;notice='';sync();render();}
function chooseProposition(value){proposition=value;draftPrompt='' ;sync();render();}
function chooseDataset(value){dataset=value;sync();render();}
function finishTrial(){sessionOpen=false;trialDone=true;screen='findings';notice='';sync();render();}
function editable(){return !['accepted','merging','merged','abandoned','outdated','conflict','returned','repairing','outage'].includes(scene);}
function status(){let text=needHuman()?'À toi de jouer · résultat prêt':scene==='merged'?'Terminé · fusion confirmée':scene==='accepted'?'Aucune action attendue · fusion en attente':scene==='abandoned'?'Terminé · aucune fusion':scene==='outdated'?'Dossier périmé · renouvellement attendu':scene==='conflict'?'Acceptation annulée · correction attendue':scene==='outage'?'Panne au lancement · réparation attendue':'L’usine travaille · aucune action attendue';return `<div class="chip ${needHuman()?'atoi':scene==='merged'?'ack':['outdated','conflict','outage'].includes(scene)?'bloque':''}">${text}</div>`;}
function heading(){return `<a class="btn ghost back" href="#inbox-list" onclick="returnToList();return false">← Retour</a><div class="quoi">${titles[scene]}</div>${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}`;}
function result(){if(!needHuman())return follow();return `<p>Les nouveaux parcours du cockpit sont prêts à essayer.</p>${version===2?'<p class="notice">Ton dernier constat a été corrigé.</p>':''}<div class="button-row">${variant==='B'?(sessionOpen?action('Continuer après mon essai',"show('trial')",true):trialDone?action('Donner mon avis',"show('findings')",true):trialLink('Essayer le cockpit ↗',true)):trialLink('Essayer le cockpit ↗',true)}${variant==='C'?action('Donner mon avis',"show('findings')"):''}</div><details><summary>Dossier et preuves</summary>${dossier()}</details>`;}
function dossier(){return `${['outdated','conflict'].includes(scene)?'<p>Ancienne version. Un nouveau dossier est attendu.</p>':''}<p class="version">Dossier ${version} · exemple</p><div class="button-row">${action('Ouvrir le dossier',"proof('Dossier complet du résultat')")}${action('Voir les preuves',"proof('Parcours, tests et relecture')")}</div><details><summary>Limites et version</summary><p>Arrêt réel et notifications non essayés.</p><p>Dossier ${version} · version ${version===1?'1111111':'2222222'} · données fictives.</p></details>`;}
function proof(title){let d=document.getElementById('proof-dialog');if(!d){d=document.createElement('dialog');d.id='proof-dialog';d.style.cssText='max-width:640px;width:90vw;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:24px';document.body.appendChild(d);}d.innerHTML=`<h2>Pièce synthétique</h2><h3>${esc(title)}</h3><p style="margin:15px 0">Version : dossier ${version}. Observation exemple : l’utilisateur ouvre le résultat, lit le dossier, essaie le produit et retrouve sa réponse dans le suivi.</p><p style="margin:15px 0">Résultat de cet exemple : parcours observé. Cette pièce ne prouve aucune livraison réelle.</p><button class="btn" onclick="document.getElementById('proof-dialog').close()">Fermer la pièce</button>`;d.showModal();notice='Pièce synthétique consultée : '+title+'.';sync();}
function trial(){if(!editable())return `<p>${scene==='outage'?'L’essai ne démarre pas. L’usine s’en occupe.':'Cette version ne peut plus être essayée.'}</p>${action('Voir le suivi',"show('follow')")}`;return `<p>${sessionOpen?'Le cockpit d’essai est ouvert dans un autre onglet.':trialDone?'Ton essai est terminé.':'Ouvre le cockpit d’essai dans un autre onglet.'}</p><div class="button-row">${variant==='B'?((sessionOpen||trialDone)?action('Donner mon avis','finishTrial()',true):trialLink('Ouvrir le cockpit d’essai',true)):trialLink(sessionOpen?'Rouvrir le cockpit d’essai':'Ouvrir le cockpit d’essai',!sessionOpen)}</div><details><summary>Dossier de cette version</summary>${dossier()}</details>`;}
function findings(){if(!editable())return follow();return `<label for="finding-text"><strong>Ton avis</strong></label><textarea id="finding-text" placeholder="Qu’est-ce qui va ou qui reste à changer ?" oninput="words=this.value;draftPrompt='';sync();updatePrepare()">${esc(words)}</textarea><div class="answer-options">${[['constats','À revoir'],['accepté','Ça me convient'],['abandonné','Abandonner']].map(([key,label])=>`<label><input type="radio" name="answer" value="${key}" ${answer===key?'checked':''} onchange="answer=this.value;draftPrompt='';sync();render()"> ${label}</label>`).join('')}</div>${answer==='abandonné'?`<label>Pourquoi ?<input type="text" id="abandon-reason" value="${esc(reason)}" oninput="reason=this.value;sync();updatePrepare()"></label>`:''}<details id="proposal-choice"><summary>Une proposition à décider ${proposition?'✓':''}</summary><p>Ajouter un filtre dans l’historique ?</p><select id="proposal-verdict" aria-label="Choix sur le filtre" onchange="chooseProposition(this.value)"><option value="">Choisir</option><option value="before" ${proposition==='before'?'selected':''}>Avant d’accepter</option><option value="plus_tard" ${proposition==='plus_tard'?'selected':''}>Plus tard</option><option value="sans_suite" ${proposition==='sans_suite'?'selected':''}>Sans suite</option></select></details>${answer==='accepté'&&proposition==='before'?'<p class="draft">Ce filtre reste à faire : choisis « À revoir ».</p>':''}<div class="button-row"><button class="btn primary" id="prepare-answer" onclick="prepare()" ${words.trim()?'':'disabled'}>Continuer avec un agent</button></div><p class="hint">Brouillon · l’agent enregistre ta réponse · consomme des tokens.</p>${draftPrompt?`<div class="box"><p>Ta réponse est prête.</p>${action('Copier pour ma session','copyPrompt()',true)}<details><summary>Voir le message</summary><textarea readonly class="prompt" id="prepared-prompt">${esc(draftPrompt)}</textarea></details></div>`:''}`;}
function canPrepare(){return editable()&&words.trim().length>0&&Boolean(proposition)&&(answer!=='abandonné'||reason.trim().length>0)&&(answer!=='accepté'||proposition!=='before');}
function updatePrepare(){const b=document.getElementById('prepare-answer');if(b)b.disabled=!words.trim();}
function prepare(){if(!canPrepare()){notice=!proposition?'Choisis quoi faire du filtre proposé.':answer==='abandonné'&&!reason.trim()?'Indique la raison de l’abandon.':'Ce filtre reste à faire avant d’accepter.';render();const choice=document.getElementById('proposal-choice');if(choice&&!proposition)choice.open=true;return;}draftPrompt=`Reprendre la session d’essai du résultat Cockpit synthétique.\nDossier ${version}, commit synthétique ${version===1?'1111111':'2222222'}, empreinte dossier-${version}.\nMa réponse préparée : ${answer}.\nMes mots exacts : ${words}\n${reason?'Raison : '+reason+'\n':''}Mon verdict sur la proposition : ${proposition}.\nContexte du constat : ${citation}.\nLire le dossier lié et vérifier qu’il est à jour. Ne pas résumer le dossier ni reformuler mes mots. Préparer les références et la réparation requises si le constat cite une exigence. Enregistrer uniquement ma réponse explicite par owner-answer, avec le commit et l’empreinte exacts du vrai dossier. Ne pas fusionner par un autre chemin.\nATTENTION : ces identifiants sont synthétiques ; ce prompt appartient au prototype et ne doit pas être exécuté.`;notice='Réponse préparée, pas encore envoyée.';sync();render();}
async function copyPrompt(){if(!draftPrompt)return;try{await navigator.clipboard.writeText(draftPrompt);notice='Prompt copié. Aucune réponse enregistrée.';}catch(e){notice='Sélectionne le texte du prompt pour le copier.';}sync();render();}
function follow(){const next={returned:'L’usine reprend tes constats.',repairing:'L’usine corrige. Tu seras averti quand tu pourras réessayer.',accepted:'Tu as accepté. La fusion est en attente.',merging:'La fusion est en cours.',merged:'La fusion est confirmée.',conflict:'La fusion a échoué. L’usine corrige ; tu jugeras une nouvelle version.',abandoned:'Chantier arrêté. Rien n’a été fusionné.',outdated:'L’usine prépare un dossier à jour.',outage:'L’usine répare le lancement.'};return `<p class="follow-status">${next[scene]||'Le résultat attend ton avis.'}</p>${['returned','repairing'].includes(scene)?`<blockquote>${esc(words||'Je ne trouve pas où revoir mon constat.')}</blockquote>`:''}<details><summary>Historique et preuves</summary>${historyRows().map(([t,b])=>`<div class="line"><strong>${t}</strong><p class="hint">${b}</p></div>`).join('')}<div class="button-row">${action('Dossier',"show('dossier')")}${scene==='merged'?action('Preuve de fusion',"proof('Fusion confirmée : résultat jugé et commit fusionné')"):''}</div></details>`;}
function historyRows(){let rows=[['15:00 · Résultat prêt','Dossier et version d’essai disponibles.']];if(['returned','repairing'].includes(scene))rows.push(['15:18 · Constats rendus','Tes mots sont liés au dossier jugé.'],[scene==='repairing'?'15:22 · Correction en cours':'15:19 · Suite préparée','Aucune fusion avant un nouveau jugement.']);if(['accepted','merging','merged','conflict'].includes(scene))rows.push(['15:18 · Accepté','Acceptation liée à la version du dossier.']);if(scene==='merging')rows.push(['15:19 · Fusion en cours','Vérifications de reprise en cours.']);if(scene==='merged')rows.push(['15:20 · Fusion confirmée','Une preuve identifie le résultat jugé et la version fusionnée.']);if(scene==='conflict')rows.push(['15:19 · Acceptation annulée','Conflit à la reprise de la branche de référence. Correction puis nouveau dossier.']);if(scene==='abandoned')rows.push(['15:18 · Abandonné','Raison : '+(reason||'Le besoin n’est plus prioritaire.')]);if(scene==='outage')rows.push(['15:08 · Essai impossible','Le produit n’a pas démarré.']);if(scene==='outdated')rows.push(['15:08 · Dossier périmé','Le résultat a changé.']);return rows;}
const content={result,dossier,trial,findings,follow};
function VariantA(){const nav=needHuman()?[['result','Résultat'],['trial','Essai'],['findings','Mon avis']]:[['follow','Suivi']];return `<nav class="tabs" aria-label="Parcours">${nav.map(([k,t])=>`<button aria-selected="${screen===k}" onclick="show('${k}')">${t}</button>`).join('')}</nav>${content[screen]()}`;}
function VariantB(){return `<section class="focus-step">${content[screen]()}${needHuman()&&screen!=='result'?`<div class="button-row">${action('← Résultat',"show('result')")}</div>`:''}</section>`;}
function VariantC(){if(!needHuman())return follow();return `<div class="button-row">${trialLink('Essayer le cockpit ↗',true)}${action('Mon avis',"show('findings')")}</div>${screen==='trial'?trial():screen==='findings'?findings():screen==='dossier'?dossier():'<p>Les nouveaux parcours du cockpit sont prêts.</p>'}${screen!=='findings'?`<details><summary>Donner mon avis</summary>${findings()}</details>`:''}${!['trial','dossier'].includes(screen)?`<details><summary>Consulter le dossier</summary>${dossier()}</details>`:''}`;}
function returnToList(){sheet=false;root.classList.remove('sheet');sync();}
function render(){detail.innerHTML=`<div class="journey">${heading()}${{A:VariantA,B:VariantB,C:VariantC}[variant]()}</div>`;root.querySelectorAll('.detail').forEach(d=>d.classList.toggle('on',d.id==='d-'+selected));root.querySelectorAll('.li').forEach(l=>l.setAttribute('aria-current',l.dataset.id===selected?'true':'false'));root.classList.toggle('sheet',sheet);let row=root.querySelector('[data-id="demo-result"]');row.hidden=!needHuman();row.querySelector('.q').textContent=scene==='new-result'?'Un nouveau résultat attend ton jugement':'Le cockpit attend ton jugement';document.querySelector('#inbox-list h2 .mono').textContent=needHuman()?'2':'1';document.getElementById('variant-name').textContent=variant+' · '+names[variant];document.getElementById('scenario').value=scene;document.querySelector('#ch-demo-result .cockpit-chantier-s').textContent=titles[scene];let track=document.querySelector('#ch-demo-result .cockpit-stepper');let phase=['accepted','merging'].includes(scene)?5:scene==='merged'?6:['returned','repairing','outage'].includes(scene)?3:4;track.innerHTML=['Cadrage','Spec','Graphe','Livraison','À juger','Accepté','Fusionné'].map((t,i)=>'<span class="'+(i<phase?'done':i===phase?'cur':'')+'" title="'+t+'"></span>').join('');track.setAttribute('aria-label',titles[scene]);let b=document.getElementById('simulate-answer');b.disabled=!draftPrompt||!canPrepare();sync();}
root.addEventListener('click',e=>{const r=e.target.closest('.li');if(r){e.preventDefault();selected=r.dataset.id;sheet=true;render();if(matchMedia('(max-width:930px)').matches)root.scrollIntoView({block:'start'});}if(e.target.closest('.back')){e.preventDefault();returnToList();}});
document.querySelectorAll('.cockpit-projects a').forEach(a=>{a.href='#d-demo-result';a.onclick=e=>{e.preventDefault();selected='demo-result';screen='follow';sheet=true;render();detail.scrollIntoView({block:'start'});};});
document.querySelector('.cockpit-projects .zone-body').insertAdjacentHTML('beforeend','<div class="button-row" style="margin-top:12px"><button class="btn" id="project-follow">Suivre le résultat du cockpit →</button><span id="journey-status" class="muted"></span></div>');
document.getElementById('project-follow').onclick=()=>{selected='demo-result';sheet=true;screen='follow';render();detail.scrollIntoView({block:'start'});};
document.querySelector('.prototype-tools').insertAdjacentHTML('beforeend','<div style="margin-top:8px"><button class="btn" id="simulate-answer" disabled>Simuler la réponse</button></div>');
document.getElementById('simulate-answer').onclick=()=>{if(!canPrepare()||!draftPrompt)return;setScene(answer==='accepté'?'accepted':answer==='abandonné'?'abandoned':'returned');};
function cycle(n){variant=variants[(variants.indexOf(variant)+n+3)%3];sync();render();}
document.getElementById('previous-variant').onclick=()=>cycle(-1);document.getElementById('next-variant').onclick=()=>cycle(1);
document.getElementById('scenario').onchange=e=>setScene(e.target.value);
document.getElementById('reset').onclick=()=>{version=1;words='';answer='constats';citation='parcours';proposition='';reason='';trialDone=false;dossierRead=false;setScene('ready');sheet=false;render();};
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowLeft')cycle(-1);if(e.key==='ArrowRight')cycle(1);});
if(qp.has('view')||scene!=='ready')sheet=true;
render();

